108	/* Discovery + PASE + commissioning delegate. Reused across calls (CHIP
109	 * delegates are registered/unregistered per attempt, not per-instance). */
110	class FluxCommissionDelegate : public chip::Controller::DevicePairingDelegate,
111	                                public chip::Controller::DeviceDiscoveryDelegate {
112	public:
113	    void OnDiscoveredDevice(const chip::Dnssd::CommissionNodeData &nodeData) override
114	    {
115	        if (!s_ctx) return;
116	        ESP_LOGI(TAG, "OnDiscoveredDevice: disc=%u cm=%u",
117	                 (unsigned)nodeData.longDiscriminator, (unsigned)nodeData.commissioningMode);
118	        /* We browse all commissionable nodes (kNone) and match the window
119	         * discriminator the phone gave us. Two things the OTBR's SRP->mDNS proxy
120	         * breaks: (1) it omits the L<disc> subtype PTR, so kLongDiscriminator
121	         * discovery never matches; (2) it drops the CM (commissioning-mode) flag,
122	         * so discovered records look like CM=0. We therefore do NOT gate on
123	         * commissioningMode — the phone just opened the ECM window with this exact
124	         * discriminator, so a discriminator match is the reliable signal. */
125	        if (nodeData.longDiscriminator != s_ctx->discriminator) return;
126	
127	        auto &ci = matter_controller_client::get_instance();
128	        ci.get_commissioner()->RegisterDeviceDiscoveryDelegate(nullptr);
129	
130	        char addr_buf[chip::Inet::IPAddress::kMaxStringLength];
131	        nodeData.ipAddress[0].ToString(addr_buf);
132	        ESP_LOGI(TAG, "discovered device: %s:%u", addr_buf, nodeData.port);
133	
134	        chip::Inet::InterfaceId ifc =
135	            nodeData.ipAddress[0].IsIPv6LinkLocal() ? nodeData.interfaceId : chip::Inet::InterfaceId::Null();
136	        chip::Transport::PeerAddress peer =
137	            chip::Transport::PeerAddress::UDP(nodeData.ipAddress[0], nodeData.port, ifc);
138	        chip::RendezvousParameters params =
139	            chip::RendezvousParameters().SetSetupPINCode(s_ctx->passcode).SetPeerAddress(peer);
140	        chip::Controller::CommissioningParameters commissioning_params;
141	        commissioning_params.SetDeviceAttestationDelegate(&s_attest_delegate);
142	
143	        CHIP_ERROR err = ci.get_commissioner()->PairDevice(s_ctx->node_id, params, commissioning_params);
144	        if (err != CHIP_NO_ERROR) {
145	            char buf[128];
146	            snprintf(buf, sizeof(buf), "PairDevice: %s", err.AsString());
147	            ESP_LOGE(TAG, "%s", buf);
148	            finish(false, buf);
149	        }
150	    }
151	
152	    void OnPairingComplete(CHIP_ERROR error) override
153	    {
154	        if (error != CHIP_NO_ERROR) {
155	            char buf[128];
156	            snprintf(buf, sizeof(buf), "PASE failed: %s", error.AsString());
157	            ESP_LOGE(TAG, "%s", buf);
158	            finish(false, buf);
159	        }
160	        /* On success, commissioning continues automatically (AutoCommissioner)
161	         * through AddNOC (flux_creds_issuer) to OnCommissioningSuccess/Failure. */
162	    }
163	
164	    void OnCommissioningSuccess(chip::PeerId peerId) override
165	    {
166	        ESP_LOGI(TAG, "commissioning success: node=%016" PRIX64, peerId.GetNodeId());
167	        finish(true, nullptr);
168	    }
169	
170	    void OnCommissioningFailure(chip::PeerId peerId, CHIP_ERROR error,
171	                                chip::Controller::CommissioningStage stage,
172	                                chip::Optional<chip::Credentials::AttestationVerificationResult>) override
173	    {
174	        char buf[128];
175	        snprintf(buf, sizeof(buf), "commissioning failed at stage %d: %s", (int)stage, error.AsString());
176	        ESP_LOGE(TAG, "%s", buf);
177	        finish(false, buf);
178	    }
179	};
