190	void commission_work(intptr_t arg)
191	{
192	    auto *w = reinterpret_cast<CommissionWorkCtx *>(arg);
193	    auto &ci = matter_controller_client::get_instance();
194	    auto *commissioner = ci.get_commissioner();
195	
196	    /* Clear a stale delegate left by a previous timed-out attempt — PairDevice
197	     * (via DiscoverCommissionableNodes) refuses to start a second pairing
198	     * process while one is still registered. */
199	    if (commissioner->GetPairingDelegate() != nullptr) {
200	        ESP_LOGW(TAG, "clearing stale pairing delegate before new commission");
201	        commissioner->RegisterPairingDelegate(nullptr);
202	        commissioner->RegisterDeviceDiscoveryDelegate(nullptr);
203	    }
204	
205	    s_ctx->passcode      = w->passcode;
206	    s_ctx->node_id       = w->node_id;
207	    s_ctx->discriminator = (uint16_t)w->discriminator;
208	    char     addr_str[46];
209	    snprintf(addr_str, sizeof(addr_str), "%s", w->address);
210	    uint16_t addr_port = w->port;
211	    delete w;
212	
213	    /* Guard: if setup_commissioner() failed at boot and the late re-init from
214	     * mfg-provision also failed (CHIP_ERROR_INCORRECT_STATE from double-Init),
215	     * the commissioner is in a broken state — fail fast with a clear message
216	     * instead of letting DiscoverCommissionableNodes crash or return a cryptic
217	     * error. The fix is to run /mfg/provision again and reboot. */
218	    if (commissioner->GetFabricIndex() == chip::kUndefinedFabricIndex) {
219	        finish(false, "commissioner not ready — run /mfg/provision or reboot");
220	        return;  /* w already freed above */
221	    }
222	
223	    commissioner->RegisterPairingDelegate(&s_delegate);
224	
225	    /* Preferred path: the phone resolved the device's commissionable IPv6 from
226	     * its own mDNS scan of the open window and handed it to us, so PASE it
227	     * directly. The controller's own DNS-SD discovery cannot identify the device
228	     * — the OTBR's SRP->mDNS proxy strips the discriminator/CM TXT on the local
229	     * query, so records resolve as disc=0 cm=0. */
230	    if (addr_str[0] != '\0') {
231	        chip::Inet::IPAddress addr;
232	        if (!chip::Inet::IPAddress::FromString(addr_str, addr)) {
233	            finish(false, "invalid device_address");
234	            return;
235	        }
236	        uint16_t p = addr_port ? addr_port : 5540;
237	        /* A link-local device_address (fe80::..) is only routable when scoped to
238	         * a local interface. The phone hands us the address with ITS own zone
239	         * (e.g. %wlan0), which is meaningless here and is dropped during parsing,
240	         * leaving a zoneless link-local that SendMessage() rejects with ERR_RTE.
241	         * Re-scope it to the controller's backbone (Ethernet) netif, which shares
242	         * the LAN link with the device. Routable (global/ULA) addresses need no
243	         * interface. Mirrors the self-discovery path in OnDiscoveredDevice(). */
244	        chip::Inet::InterfaceId ifc = chip::Inet::InterfaceId::Null();
245	        if (addr.IsIPv6LinkLocal()) {
246	            esp_netif_t *bb = esp_netif_get_handle_from_ifkey(FLUX_BACKBONE_IFKEY);
247	            struct netif *bb_netif =
248	                bb ? static_cast<struct netif *>(esp_netif_get_netif_impl(bb)) : nullptr;
249	            if (bb_netif != nullptr) {
250	                ifc = chip::Inet::InterfaceId(bb_netif);
251	            } else {
252	                ESP_LOGW(TAG, "link-local device_address but backbone netif %s "
253	                              "unavailable — PASE send will likely fail",
254	                         FLUX_BACKBONE_IFKEY);
255	            }
256	        }
257	        chip::Transport::PeerAddress peer =
258	            chip::Transport::PeerAddress::UDP(addr, p, ifc);
259	        chip::RendezvousParameters params =
260	            chip::RendezvousParameters().SetSetupPINCode(s_ctx->passcode).SetPeerAddress(peer);
261	        chip::Controller::CommissioningParameters cparams;
262	        cparams.SetDeviceAttestationDelegate(&s_attest_delegate);
263	        ESP_LOGI(TAG, "PASE direct to [%s]:%u iface=%s (skipping DNS-SD)", addr_str,
264	                 (unsigned)p, addr.IsIPv6LinkLocal() ? FLUX_BACKBONE_IFKEY : "none");
265	        CHIP_ERROR err = commissioner->PairDevice(s_ctx->node_id, params, cparams);
266	        if (err != CHIP_NO_ERROR) {
267	            char buf[128];
268	            snprintf(buf, sizeof(buf), "PairDevice: %s", err.AsString());
269	            ESP_LOGE(TAG, "%s", buf);
270	            finish(false, buf);
271	        }
272	        return;
273	    }
274	
275	    /* Fallback (no address supplied): browse all commissionable nodes (kNone) and
276	     * match the discriminator in OnDiscoveredDevice. Discriminator-subtype
277	     * discovery (kLongDiscriminator) fails over the OTBR because the SRP->mDNS
278	     * proxy omits the L<disc> subtype PTR. */
279	    commissioner->RegisterDeviceDiscoveryDelegate(&s_delegate);
280	    chip::Dnssd::DiscoveryFilter filter(chip::Dnssd::DiscoveryFilterType::kNone);
281	    CHIP_ERROR disc_err = commissioner->DiscoverCommissionableNodes(filter);
282	    if (disc_err != CHIP_NO_ERROR) {
283	        commissioner->RegisterDeviceDiscoveryDelegate(nullptr);
284	        commissioner->RegisterPairingDelegate(nullptr);
285	        char buf[128];
286	        snprintf(buf, sizeof(buf), "DiscoverCommissionableNodes: %s", disc_err.AsString());
287	        ESP_LOGE(TAG, "%s", buf);
288	        finish(false, buf);
289	    }
290	}
