extern "C" esp_err_t flux_commission_device(
    uint32_t passcode, uint32_t discriminator, uint64_t requested_node_id,
    const char *device_address, uint16_t device_port,
    uint64_t *out_node_id, uint64_t *out_fabric_id,
    char *error_buf, size_t error_buf_len)
{
    if (passcode == 0) {
        snprintf(error_buf, error_buf_len, "passcode is required");
        return ESP_ERR_INVALID_ARG;
    }

    /* Idempotency: replay the last successful commission for a repeated request
     * to the same device within a short window, instead of re-running PASE
     * against a now-closed window (which fails and masks the original success). */
    if (device_address && device_address[0] != '\0' && s_last.when_us != 0 &&
        strncmp(device_address, s_last.address, sizeof(s_last.address)) == 0 &&
        (esp_timer_get_time() - s_last.when_us) < kCommissionCacheTtlUs) {
        ESP_LOGW(TAG, "duplicate /commission for %s — replaying cached result (node=%016" PRIX64 ")",
                 device_address, s_last.node_id);
        *out_node_id   = s_last.node_id;
        *out_fabric_id = s_last.fabric_id;
        return ESP_OK;
    }

