172	// ── CommissioningController ────────────────────────────────────────────────────
173	
174	/// Owns all commissioning flow logic: payload parsing, BLE permission checks,
175	/// event-stream subscription, the CREDENTIALS_NEEDED handshake, human-readable
176	/// log mapping, device name generation, and QR payload persistence.
177	///
178	/// The widget keeps only UI-only state (mode toggle, form controllers) and
179	/// injects two callbacks so the controller never touches [BuildContext]:
180	///   - [requestBlePermissions] - shows OS dialogs, returns true if granted
181	///   - [onNeedsCredentials]    - shows credential sheet, returns creds or null
182	class CommissioningController extends ChangeNotifier {
183	  CommissioningController({
184	    required MatterCommissionPort port,
185	    required DeviceProvider provider,
186	    required this.requestBlePermissions,
187	    required this.onNeedsCredentials,
188	    this.threadDataset = _returnEmpty,
189	    this.controllerService,
190	  }) : _port = port,
191	       _provider = provider;
192	
193	  final MatterCommissionPort _port;
194	  final DeviceProvider _provider;
195	
196	  /// The connected Flux hub's CoAP client.  Commissioning requires it: the
197	  /// device is handed off to the controller (`POST /commission`), which
198	  /// commissions it onto its own fabric.  Null when no hub is connected — in
199	  /// which case [start] fails fast (there is no standalone commissioning).
200	  final FluxCoapService? controllerService;
201	
202	  final Future<bool> Function() requestBlePermissions;
203	  /// Called when the device needs credentials during commissioning.
204	  /// [isThread] is true when the device is a Thread device, false for WiFi.
205	  final Future<CommissionCredentials?> Function(bool isThread) onNeedsCredentials;
206	  final String Function() threadDataset;
207	
208	  // ── Public state ──────────────────────────────────────────────────────────
209	
210	  CommissionPhase phase = CommissionPhase.idle;
211	  ParsedPayload? parsed;
212	  String? parseError;
213	  bool parsing = false;
214	  String? rawPayload;
215	  List<LogEntry> rawLog = const [];
216	  List<HumanEntry> humanLog = const [];
217	  int stageIdx = -1;
218	  MatterDevice? result;
219	  String? error;
220	
221	  // ── Private ───────────────────────────────────────────────────────────────
222	
223	  StreamSubscription<String>? _eventSub;
224	
225	  /// Monotonically-increasing session counter.  When reset() or a new start()
226	  /// is called, any in-flight start() from a previous session detects the
227	  /// mismatch and discards its result.
228	  int _sessionId = 0;
229	
230	  static String _returnEmpty() => '';
231	
232	  // ── setPayload ────────────────────────────────────────────────────────────
233	
234	  /// Parses [raw] and updates [parsed] / [parseError] / [phase].
235	  /// After this returns the caller should read those fields and decide whether
236	  /// to call [start].  Auto-starting from inside the controller is intentionally
237	  /// not supported - the widget has the authoritative thread-selected state
238	  /// needed to pick the correct network type.
239	  Future<void> setPayload(String raw) async {
240	    rawPayload = raw;
241	    parsed = null;
242	    parseError = null;
243	    parsing = true;
244	    phase = CommissionPhase.parsing;
245	    notifyListeners();
246	
247	    final p = await _port.parsePayload(raw);
248	
249	    if (p == null) {
250	      parsing = false;
251	      parseError = 'Could not parse payload';
252	      phase = CommissionPhase.idle;
253	      notifyListeners();
254	      return;
255	    }
256	
257	    parsing = false;
258	    parsed = p;
259	    phase = CommissionPhase.parsed;
260	    notifyListeners();
261	
262	    debugPrint(
263	      '🔍 parsed payload: caps=${p.discoveryCapabilities} '
264	      'prefersBle=${p.prefersBle} hasOnNetwork=${p.hasOnNetwork} '
265	      'capabilitiesUnknown=${p.capabilitiesUnknown} '
266	      '→ method=${suggestMethod(p)} netType=${suggestNetType(p, threadDataset: threadDataset())}',
267	    );
268	
269	    await QrPayloadService.save(raw);
270	  }
271	
272	  // ── start ─────────────────────────────────────────────────────────────────
273	
274	  /// Runs the full commissioning flow for the currently parsed payload.
275	  ///
276	  /// Returns normally once commissioning has either succeeded ([phase] == done)
277	  /// or failed ([phase] == failed).  After the call the widget should navigate
278	  /// on success or display the failure footer.
279	  Future<void> start(CommissionConfig config) async {
280	    if (rawPayload == null || parsed == null) return;
281	
282	    // Commission-then-handoff requires a hub: the device is commissioned onto a
283	    // throwaway phone fabric, then handed to the controller.  Without a hub
284	    // there is nothing to hand off to, so fail fast (no standalone path).
285	    if (controllerService == null) {
286	      error = 'No Flux controller connected — connect a controller before adding devices';
287	      phase = CommissionPhase.failed;
288	      notifyListeners();
289	      return;
290	    }
291	
292	    if (config.method == CommissionMethod.ble) {
293	      if (!await requestBlePermissions()) return;
294	    }
295	
296	    final sessionId = ++_sessionId;
297	
298	    rawLog = const [];
299	    humanLog = const [];
300	    stageIdx = -1;
301	    result = null;
302	    error = null;
303	    phase = CommissionPhase.running;
304	    notifyListeners();
305	
306	    final name = _generateName(_provider.devices.map((d) => d.name).toList());
307	    _appendRaw('Commissioning "$name"...', level: LogLevel.step);
308	
309	    _eventSub = _port.commissionEvents.listen(_onEvent);
310	
311	    // Pre-collect Wi-Fi credentials for BLE+WiFi when SSID is not filled in.
312	    // Only fires when the user has explicitly selected WiFi (netType 1) - for
313	    // unknown/auto-detect (netType 2) we let onReadCommissioningInfo decide.
314	    var cfg = config;
315	    if (config.method == CommissionMethod.ble &&
316	        config.netType == 1 &&
317	        config.wifiSsid.isEmpty) {
318	      final creds = await onNeedsCredentials(false); // false = WiFi
319	      if (sessionId != _sessionId) return; // cancelled while awaiting
320	      if (creds == null) {
321	        await _eventSub?.cancel();
322	        _eventSub = null;
323	        rawLog = const [];
324	        humanLog = const [];
325	        phase = CommissionPhase.idle;
326	        notifyListeners();
327	        return;
328	      }
329	      cfg = config.copyWith(
330	        wifiSsid: creds.wifiSsid ?? '',
331	        wifiPassword: creds.wifiPassword ?? '',
332	        threadDatasetHex: creds.threadDatasetHex ?? '',
333	      );
334	    }
335	
336	    NetworkType networkType = NetworkType.ethernet;
337	    CommissionResult commissionResult;
338	
339	    _provider.beginCommissioning();
340	
341	    if (cfg.method == CommissionMethod.ble) {
342	      // ── BLE commissioning (phone always commissions) ──────────────────────
343	      networkType = switch (cfg.netType) {
344	        0 => NetworkType.thread,
345	        1 => NetworkType.wifi,
346	        _ => NetworkType.ethernet,
347	      };
348	
349	      // Resolve which Thread network to commission onto.  Precedence:
350	      //   1. an explicit dataset chosen for THIS commission (expert mode),
351	      //   2. the HUB's Thread network — the hub owns it, so devices must join
352	      //      its mesh to be reachable by the controller and every phone,
353	      //   3. the app's locally-configured active dataset (standalone fallback).
354	      var threadHex = cfg.threadDatasetHex.replaceAll(RegExp(r'\s'), '');
355	
356	      if (threadHex.isEmpty && controllerService != null && cfg.netType == 0) {
357	        _appendRaw('▶ Using the controller\'s Thread network…', level: LogLevel.step);
358	        final fetched = await controllerService!.getThreadDatasetHex();
359	        if (fetched != null && fetched.isNotEmpty) {
360	          threadHex = fetched;
361	          _appendRaw('✓ Controller Thread network (${fetched.length ~/ 2} bytes)',
362	              level: LogLevel.success);
363	        } else {
364	          _appendRaw('⚠ Controller has no Thread network — using app dataset if set',
365	              level: LogLevel.info);
366	        }
367	      }
368	
369	      // Fallback: the app's own active dataset (e.g. standalone / hub has none).
370	      if (threadHex.isEmpty && cfg.netType == 0) {
371	        threadHex = threadDataset().replaceAll(RegExp(r'\s'), '');
372	      }
373	
374	      _appendRaw('▶ Connecting to device via Bluetooth…', level: LogLevel.step);
375	      commissionResult = switch (cfg.netType) {
376	        0 => await _port.commissionDevice(rawPayload!, threadDatasetHex: threadHex),
377	        1 => await _port.commissionDevice(rawPayload!,
378	                wifiSsid: cfg.wifiSsid, wifiPassword: cfg.wifiPassword),
379	        _ => await _port.commissionDevice(rawPayload!),
380	      };
381	    } else {
382	      // ── IP / on-network commissioning ─────────────────────────────────────
383	      networkType = NetworkType.ethernet;
384	      if (cfg.ipAddress.trim().isEmpty) {
385	        _appendRaw('🔍 No IP address — using DNS-SD on-network discovery…',
386	            level: LogLevel.info);
387	        commissionResult = await _port.commissionViaCode(setupCode: rawPayload!);
388	      } else {
389	        commissionResult = await _port.commissionViaIp(
390	          ipAddress: cfg.ipAddress,
391	          discriminator: cfg.discriminator > 0
392	              ? cfg.discriminator
393	              : (parsed!.discriminator > 0 ? parsed!.discriminator : 3840),
394	          setupPinCode: cfg.setupPinCode,
395	        );
396	      }
397	    }
398	
399	    await _eventSub?.cancel();
400	    _eventSub = null;
401	
402	    if (sessionId != _sessionId) return; // cancelled while commission ran
403	
404	    if (!commissionResult.success) {
405	      error = commissionResult.error ?? 'Commissioning failed';
406	      _provider.failCommissioning(error);
407	      phase = CommissionPhase.failed;
408	      _appendRaw(error!, level: LogLevel.error);
409	      notifyListeners();
410	      return;
411	    }
412	
413	    final nodeId = commissionResult.nodeId!;
414	    final svc    = controllerService!;
415	    var managedBy = ManagedBy.phone;
416	
417	    // ── Commission-then-handoff (standard Matter multi-admin) ─────────────────
418	    // Phone Pass-1 is done; stop projecting its remaining stages onto the human
419	    // track and switch to handoff milestones.
420	    stageIdx = kCommissionStages.length;
421	    // 1. Open an ECM window on the device (still on our throwaway fabric).
422	    _appendRaw('▶ Opening commissioning window…', level: LogLevel.step);
423	    final window = await _port.openCommissioningWindow(nodeId);
424	    if (sessionId != _sessionId) return; // cancelled while awaiting
425	    if (window == null || window.passcode == 0 || window.discriminator == 0) {
426	      _failHandoff('Could not open a commissioning window on the device');
427	      return;
428	    }
429	    _appendRaw('✓ Window open (disc=${window.discriminator})', level: LogLevel.success);
430	
431	    // 2. Hand the device to the controller — it commissions onto its OWN fabric
432	    //    with its own CA and registers + subscribes it itself.
433	    _appendRaw('▶ Handing the device to the controller…', level: LogLevel.step);
434	    _appendHuman('CONTROLLER COMMISSIONING');
435	    // Pass nodeId 0 so the controller assigns the device's node ID on its own
436	    // fabric. The controller owns id assignment there, and this avoids feeding
437	    // the phone-fabric node ID through the wire (the proto field is uint64; a
438	    // node ID with bit 31 set must not be sign-extended). Our post-handoff
439	    // fabric gate uses the phone's own CASE session, not this id.
440	    // device_address/port come from the phone's own mDNS scan of the open window
441	    // (window.ipv6Address). The controller PASEs this directly because its own
442	    // DNS-SD discovery can't identify the device over the OTBR proxy.
443	    final handoff = await svc.commission(
444	      passcode:      window.passcode,
445	      discriminator: window.discriminator,
446	      nodeId:        0,
447	      name:          name,
448	      deviceType:    commissionResult.deviceTypeId ?? 0,
449	      deviceAddress: window.ipv6Address,
450	      devicePort:    window.port,
451	    );
452	    if (sessionId != _sessionId) return;
453	    if (handoff == null || !handoff.success) {
454	      // Controller could not commission — NEVER remove our fabric; the device
455	      // stays recoverable on the phone's throwaway fabric.
456	      final why = (handoff?.error.isNotEmpty ?? false)
457	          ? handoff!.error
458	          : 'the controller could not commission the device';
459	      _failHandoff('Handoff failed — $why');
460	      return;
461	    }
462	
463	    final controllerFabricHex =
464	        handoff.fabricId.toHexString().toUpperCase().padLeft(16, '0');
465	    _appendRaw('✓ Controller commissioned the device (fabric 0x$controllerFabricHex)',
466	        level: LogLevel.success);
467	    _appendHuman('CONTROLLER COMMISSIONED');
468	    managedBy = ManagedBy.controller;
469	
470	    // 3. Safety gate + 4. RemoveFabric.  The controller's fabric MUST be present
471	    //    on the device before we remove our own; on any doubt we keep our fabric
472	    //    (the device stays recoverable, never orphaned).
473	    _appendRaw('▶ Verifying the controller fabric on the device…', level: LogLevel.step);
474	    _appendHuman('VERIFYING');
475	    final fabrics = await _port.readFabrics(nodeId) ?? const <FabricDescriptor>[];
476	    if (sessionId != _sessionId) return;
477	
478	    bool isControllerFabric(String id) =>
479	        id.replaceFirst(RegExp('^0x', caseSensitive: false), '')
480	          .toUpperCase()
481	          .padLeft(16, '0') == controllerFabricHex;
482	
483	    if (!fabrics.any((f) => isControllerFabric(f.fabricId))) {
484	      _appendRaw(
485	          '⚠ Controller fabric not yet visible on the device — leaving this phone\'s '
486	          'fabric in place (the device stays recoverable)',
487	          level: LogLevel.info);
488	    } else {
489	      final mine = fabrics.where((f) => !isControllerFabric(f.fabricId)).toList();
490	      if (mine.length == 1) {
491	        _appendRaw('▶ Removing this phone\'s temporary fabric…', level: LogLevel.step);
492	        final removed = await _port.removeFabric(nodeId, mine.single.fabricIndex);
493	        if (sessionId != _sessionId) return;
494	        _appendRaw(
495	            removed
496	                ? '✓ Device is now on the controller fabric only'
497	                : '⚠ Could not remove this phone\'s fabric — the controller still controls the device',
498	            level: removed ? LogLevel.success : LogLevel.info);
499	      } else {
500	        _appendRaw(
501	            '⚠ Could not uniquely identify this phone\'s fabric '
502	            '(${mine.length} candidates) — leaving it in place',
503	            level: LogLevel.info);
504	      }
505	    }
506	
507	    final device = await _provider.registerCommissionedDevice(
508	      commissionResult,
509	      name,
510	      networkType,
511	      managedBy: managedBy,
512	    );
513	    result = device;
514	    phase = CommissionPhase.done;
515	    _appendHuman('COMPLETE', color: const Color(0xFF34A853));
516	    await QrPayloadService.clear();
517	    notifyListeners();
518	  }
