520	  /// Fails the current commission with [msg].  Used for handoff failures where
521	  /// the device remains on the phone's throwaway fabric (never orphaned).
522	  void _failHandoff(String msg) {
523	    error = msg;
524	    _provider.failCommissioning(msg);
525	    phase = CommissionPhase.failed;
526	    _appendRaw(msg, level: LogLevel.error);
527	    _appendHuman('FAILED', color: const Color(0xFFE53935));
528	    notifyListeners();
529	  }
