533	  void reset() {
534	    _sessionId++; // invalidate in-flight start()
535	    _eventSub?.cancel();
536	    _eventSub = null;
537	    _provider.failCommissioning(null);
538	    phase = CommissionPhase.idle;
539	    parsed = null;
540	    rawPayload = null;
541	    parseError = null;
542	    parsing = false;
543	    rawLog = const [];
544	    humanLog = const [];
545	    stageIdx = -1;
546	    result = null;
547	    error = null;
