557	  // ── Static helpers ────────────────────────────────────────────────────────
558	
559	  static CommissionMethod suggestMethod(ParsedPayload p) =>
560	      (p.prefersBle || p.capabilitiesUnknown) ? CommissionMethod.ble : CommissionMethod.ip;
561	
562	  /// Returns the suggested network type for [p].
563	  ///
564	  /// [threadDataset] - the current dataset hex (used when non-empty).
565	  /// [threadSelected] - true if the user has explicitly selected a Thread
566	  ///   dataset (even the "Empty dataset" option); overrides the empty-string
567	  ///   check so an empty dataset still defaults to Thread.
568	  static int suggestNetType(ParsedPayload p, {String threadDataset = '', bool threadSelected = false}) {
569	    if (p.hasOnNetwork) return 2;
570	    if (p.discoveryCapabilities.contains(DiscoveryCapability.wifiPaf)) return 1;
571	    if (threadSelected || threadDataset.trim().isNotEmpty) return 0;
572	    // Unknown BLE device with no credentials configured: default to None (2)
573	    // so the app doesn't assume WiFi. The actual type is learned from
574	    // onReadCommissioningInfo after BLE connects.
575	    return 2;
576	  }
