590	  // ── Event processing ──────────────────────────────────────────────────────
591	
592	  void _onEvent(String event) {
593	    var lvl = LogLevel.info;
594	    if (event.startsWith('✓') || event.startsWith('🎉')) lvl = LogLevel.success;
595	    if (event.startsWith('✗')) lvl = LogLevel.error;
596	    if (event.startsWith('▶')) lvl = LogLevel.step;
597	
598	    const stagePrefix = '▶ Stage: ';
599	    if (event.startsWith(stagePrefix)) {
600	      final stageName = event.substring(stagePrefix.length).trim();
601	      final idx = kCommissionStages.indexOf(stageName);
602	      if (idx >= 0) stageIdx = idx;
603	    }
604	
605	    if (event.contains('CREDENTIALS_NEEDED:THREAD')) {
606	      scheduleMicrotask(() => _handleCredentialsNeeded(true));
607	    } else if (event.contains('CREDENTIALS_NEEDED')) {
608	      // CREDENTIALS_NEEDED:WIFI or legacy plain CREDENTIALS_NEEDED
609	      scheduleMicrotask(() => _handleCredentialsNeeded(false));
610	    }
611	
612	    final human = _eventToHumanText(event);
613	    if (human != null) {
614	      Color? humanColor;
615	      if (human == 'COMPLETE') humanColor = const Color(0xFF34A853);
616	      if (human == 'FAILED') humanColor = const Color(0xFFE53935);
617	      humanLog = [...humanLog, HumanEntry(text: human, color: humanColor ?? _humanColorFor(lvl))];
618	    }
619	
620	    _appendRaw(event, level: lvl);
621	  }
622	
623	  Future<void> _handleCredentialsNeeded(bool isThread) async {
624	    final creds = await onNeedsCredentials(isThread);
625	    if (creds?.wifiSsid != null && creds!.wifiSsid!.isNotEmpty) {
626	      await _port.provideCredentials(ssid: creds.wifiSsid, password: creds.wifiPassword);
627	    } else if (creds?.threadDatasetHex != null && creds!.threadDatasetHex!.isNotEmpty) {
628	      await _port.provideCredentials(threadDatasetHex: creds.threadDatasetHex);
629	    } else {
630	      await _port.provideCredentials();
631	    }
632	  }
633	
634	  void _appendRaw(String msg, {LogLevel level = LogLevel.info}) {
635	    rawLog = [...rawLog, LogEntry(message: msg, level: level)];
636	    notifyListeners();
637	  }
638	
639	  /// Appends a milestone to the human-readable progress track.
640	  ///
641	  /// The controller handoff runs AFTER the phone's Pass-1 commissioning (whose
642	  /// milestones arrive via [commissionEvents]). Without this the human track
643	  /// would freeze at the phone's completion — and read as fully "done" — while
644	  /// the hub is still commissioning the device onto its own fabric.
645	  void _appendHuman(String text, {Color? color}) {
646	    humanLog = [...humanLog, HumanEntry(text: text, color: color)];
647	    notifyListeners();
648	  }
649	
650	  static Color? _humanColorFor(LogLevel lvl) => switch (lvl) {
651	    LogLevel.success => const Color(0xFF34A853),
652	    _ => null,
653	  };
654	
655	  // ── Human text mapping ────────────────────────────────────────────────────
656	
657	  static String? _eventToHumanText(String event) {
658	    const stagePrefix = '▶ Stage: ';
659	    if (event.startsWith(stagePrefix)) {
660	      final name = event.substring(stagePrefix.length).trim();
661	      return kCommissionStageHuman[name] ?? name.toUpperCase();
662	    }
663	    if (event.contains('BLE scanning')) return 'BLUETOOTH SCANNING';
664	    if (event.contains('Found device')) return 'DEVICE FOUND';
665	    if (event.contains('GATT connecting')) return 'BLE CONNECTING';
666	    if (event.contains('BLE connected')) return 'BLE CONNECTED';
667	    if (event.contains('Closing previous BLE')) return 'RECONNECTING';
668	    if (event.contains('Starting CHIP commissioning')) return 'STARTING COMMISSIONING';
669	    if (event.contains('Commissioning via IP')) return 'IP CONNECTING';
670	    if (event.contains('Device:') && event.contains('VID=')) return 'DEVICE IDENTIFIED';
671	    if (event.contains('ICD device detected')) return 'ICD REGISTERING';
672	    if (event.contains('Using Thread')) return 'THREAD DATASET';
673	    if (event.contains('Using Wi-Fi')) return 'WIFI CREDENTIALS';
674	    // The phone's Pass-1 completion is NOT the end of the flow — the controller
