cd /home/tado/workspace/flux
python3 - <<'EOF'
import re
block = '''
// GET /commission/events (CoAP Observe)
// Fine-grained progress of the /commission currently in flight.  A plain GET
// returns the LATEST event (seq 0 = nothing in flight yet); Observe
// notifications fire on every stage change.  seq is monotonic so the app can
// drop stale or duplicate notifies.  stage is a CHIP CommissioningStage name
// exactly as StageToString() renders it (e.g. "SendNOC", "Cleanup") — the
// same names the phone SDK reports during its own commissioning — or one of
// the controller's discovery pseudo-stages that precede PASE:
//   "SrpLookup"     checking the controller's own SRP server table
//   "Discovering"   commissionable DNS-SD browse on the LAN
//   "Found"         device located (detail = address); PASE starting
// Only one commission runs at a time, so the stream is global.  Events are
// advisory (UI progress) — the POST /commission reply remains the source of
// truth for success/failure.
message CommissionEvent {
    uint32 seq    = 1;
    string stage  = 2;
    bool   failed = 3;  // set on commissioning failure (detail = error text)
    string detail = 4;  // found address, error text, ...
}
'''
anchor = re.compile(r'(message CommissionResult \{[^}]*\}\n)', re.S)
for path in ['flux-proto/proto/flux.proto',
             'flux-app/flux-interface/proto/flux.proto',
             'flux-controller/proto/proto/flux.proto']:
    src = open(path).read()
    if 'CommissionEvent' in src:
        print(f'{path}: already present, skipped'); continue
    new, n = anchor.subn(lambda m: m.group(1) + block, src, count=1)
    assert n == 1, path
    open(path, 'w').write(new)
    print(f'{path}: inserted')

opts = '''flux.CommissionEvent.stage              max_size:40
flux.CommissionEvent.detail             max_size:64
'''
for path in ['flux-proto/proto/flux.options',
             'flux-app/flux-interface/proto/flux.options',
             'flux-controller/proto/proto/flux.options']:
    src = open(path).read()
    if 'CommissionEvent' in src: print(f'{path}: already present, skipped'); continue
    tag = 'flux.CommissionResult.error             max_size:256\n'
    assert tag in src, path
    open(path, 'w').write(src.replace(tag, tag + opts, 1))
    print(f'{path}: options added')
EOF

