  bool    _busy = false;
  String? _error;
  bool    _done = false;

  Future<void> _split() async {
    setState(() { _busy = true; _error = null; });
    final res = await widget.service.splitThreadNetwork();
    if (!mounted) return;
    if (res == null) {
      setState(() {
        _busy = false;
        _error = 'The controller did not complete the split. It may not support '
