257	    // Horizontal gridlines + ct/kWh labels.
258	    final tp = TextPainter(textDirection: TextDirection.ltr);
259	    final gridPaint = Paint()..color = axisColor..strokeWidth = 1;
260	    for (var v = lo; v <= hi + 0.001; v += step) {
261	      final gy = yPrice(v);
262	      canvas.drawLine(Offset(_padLeft, gy), Offset(size.width, gy),
263	          gridPaint..color = axisColor.withValues(alpha: v == 0 ? 0.5 : 0.22));
264	      tp
265	        ..text = TextSpan(
266	            text: step >= 1 ? v.toStringAsFixed(0) : v.toStringAsFixed(1),
267	            style: TextStyle(color: labelColor, fontSize: 9))
268	        ..layout();
269	      tp.paint(canvas, Offset(_padLeft - tp.width - 4, gy - tp.height / 2));
270	    }
271	
272	    // Clip data traces to the plot rect so lines/steps never spill past the
273	    // axes into the padding or neighbouring widgets.
274	    canvas.save();
275	    canvas.clipRect(Rect.fromLTRB(_padLeft, _padTop, size.width, _padTop + plotH));
