/*
 * flux_prices_awattar — aWATTar day-ahead provider (DE/AT).
 *
 * Free, no API key. GET https://api.awattar.de|at/v1/marketdata returns raw EPEX
 * spot in hourly intervals as JSON:
 *   {"object":"list","data":[
 *     {"start_timestamp":<ms>,"end_timestamp":<ms>,"marketprice":68.9,"unit":"Eur/MWh"}, ...]}
 * marketprice is EUR/MWh (may be negative) → stored as µEUR/kWh (×1000).
 */
#include "flux_prices_provider.h"
#include "flux_prices_http.h"

#include <math.h>
#include <string.h>
#include <stdio.h>
#include <strings.h>

#include "cJSON.h"
#include "esp_log.h"

static const char *TAG = "flux_awattar";

#define AWATTAR_MAX_BODY  (64 * 1024)

static esp_err_t awattar_fetch(const flux_PricingConfig *cfg,
                               int64_t want_from, int64_t want_to,
                               flux_PriceCurve *out)
{
    (void)want_to;
    const char *host = "api.awattar.de";
    if (cfg->zone[0] && strcasecmp(cfg->zone, "AT") == 0) host = "api.awattar.at";

    /* start filters to entries at/after `want_from` (ms). Floor to the top of the
     * hour so the CURRENT interval is included (aWATTar drops intervals whose
     * start precedes `start`) — otherwise flux_prices_at(now) has no coverage
     * until the next hour. end omitted → provider returns today + tomorrow. */
    int64_t from = want_from > 0 ? want_from - (want_from % 3600) : 0;
    char url[128];
    snprintf(url, sizeof(url), "https://%s/v1/marketdata?start=%lld000",
             host, (long long)from);

        next_try = s_next_try_us;
        last_ok  = s_last_ok_us;
        fail     = s_fail;
        int64_t covered_until = curve_end_locked();
        unlock();

        if (cfg.enabled && flux_time_is_synced()) {
            int64_t now    = (int64_t)time(NULL);
            int64_t now_us = esp_timer_get_time();
            int64_t forward = covered_until - now;

            bool want     = forward < REFRESH_HORIZON_S;
            bool cooldown = (fail == 0 && last_ok != 0 &&
                             (now_us - last_ok) < (int64_t)MIN_OK_INTERVAL_S * 1000000);

            if (want && !cooldown && now_us >= next_try) {
                esp_err_t e = do_fetch(&cfg, now);
                lock();
                if (e == ESP_OK) {
                    s_fail = 0; s_last_ok_us = esp_timer_get_time(); s_next_try_us = 0;
                } else {
                    if (s_fail < 10) s_fail++;
                    int shift = s_fail < 4 ? s_fail : 4;
                    int64_t bo = (int64_t)RETRY_BASE_S << shift;
                    if (bo > MAX_RETRY_S) bo = MAX_RETRY_S;
                    s_next_try_us = esp_timer_get_time() + bo * 1000000;
                    ESP_LOGW(TAG, "fetch failed (%s) — retry in %llds (attempt %d)",
                             esp_err_to_name(e), (long long)bo, s_fail);
                }
                unlock();
            }

            /* keep the cached curve's stale flag honest for readers */
            lock();
            if (s_have_curve) s_curve.stale = (curve_end_locked() <= now);
            unlock();
        }

        vTaskDelay(pdMS_TO_TICKS(TICK_MS));
    }
}

void flux_prices_start(void)
{
    lock();
    if (!s_loaded) { nvs_load(); s_loaded = true; }
    bool enabled = s_cfg.enabled;
    unlock();
    /* 32 KiB PSRAM stack: do_fetch runs a full TLS handshake (esp-tls/mbedTLS) +
     * cJSON_Parse of a body up to 64 KB with a ~1.2 KB PriceCurve live on-frame;
     * 8 KiB internal was too tight and risked a silent overflow. PSRAM keeps it
     * off scarce internal RAM (same as the energy history worker). */
    if (xTaskCreateWithCaps(prices_task, "flux_prices", 32768, NULL, 3, NULL,
                            MALLOC_CAP_SPIRAM) != pdPASS) {
        ESP_LOGE(TAG, "failed to create price task — pricing disabled");
        return;
    }
    ESP_LOGI(TAG, "price task started (%s)", enabled ? "enabled" : "disabled — opt-in via /prices/config");
}

/* ── Public accessors ────────────────────────────────────────────────────── */

esp_err_t flux_prices_get_config(flux_PricingConfig *out)
{
    if (!out) return ESP_ERR_INVALID_ARG;
    lock();
    if (!s_loaded) { nvs_load(); s_loaded = true; }
    *out = s_cfg;
    unlock();
    return ESP_OK;
}

esp_err_t flux_prices_set_config(const flux_PricingConfig *cfg)
{
    if (!cfg) return ESP_ERR_INVALID_ARG;
    lock();
    s_cfg = *cfg;
    s_loaded = true;
    s_fail = 0; s_next_try_us = 0; s_last_ok_us = 0;   /* nudge a prompt refresh */
    s_have_curve = false;   /* provider/zone may have changed → old curve is stale */
    unlock();
    esp_err_t err = nvs_save_blob(NVS_KEY_CFG, flux_PricingConfig_fields, cfg,
                                  flux_PricingConfig_size);
    ESP_LOGI(TAG, "config set: enabled=%d provider='%s' zone='%s' (persist %s)",
             cfg->enabled, cfg->provider, cfg->zone, esp_err_to_name(err));
    return err;   /* propagate NVS failure so the client isn't told "ok" falsely */
}

esp_err_t flux_prices_get_curve(flux_PriceCurve *out)
{
    if (!out) return ESP_ERR_INVALID_ARG;
    lock();
    if (!s_have_curve) { unlock(); return ESP_ERR_NOT_FOUND; }
    if (flux_time_is_synced())
        s_curve.stale = (curve_end_locked() <= (int64_t)time(NULL));
    *out = s_curve;
    unlock();
    return ESP_OK;
}

esp_err_t flux_prices_at(int64_t epoch, int32_t *ueur_per_kwh)
{
    if (!ueur_per_kwh) return ESP_ERR_INVALID_ARG;
    if (epoch == 0) epoch = (int64_t)time(NULL);
    lock();
    esp_err_t rc = ESP_ERR_NOT_FOUND;
    if (s_have_curve && s_curve.resolution_seconds) {
        int64_t idx = (epoch - s_curve.start_epoch) / s_curve.resolution_seconds;
        if (idx >= 0 && idx < s_curve.prices_count) {
            *ueur_per_kwh = s_curve.prices[idx];
            rc = ESP_OK;
        }
    }
    unlock();
    return rc;
}

