const char *host = "api.awattar.de";
if (cfg->zone[0] && strcasecmp(cfg->zone, "AT") == 0) host = "api.awattar.at";

/* start filters to entries at/after `want_from` (ms). Floor to the top of the
 * hour so the CURRENT interval is included (aWATTar drops intervals whose
 * start precedes `start`) — otherwise flux_prices_at(now) has no coverage
 * until the next hour.
 *
 * `end` is REQUIRED once `start` reaches into the past: with start alone the
 * API returns exactly 24 h from start, which would hand back only history and
 * no forecast at all. Ceil to the hour so the last wanted interval is whole.
 * Beyond published data aWATTar simply returns fewer intervals. */
int64_t from = want_from > 0 ? want_from - (want_from % 3600) : 0;
int64_t to   = want_to > from ? want_to + (want_to % 3600 ? 3600 - want_to % 3600 : 0)
                              : from + 48 * 3600;
char url[160];
snprintf(url, sizeof(url), "https://%s/v1/marketdata?start=%lld000&end=%lld000",
         host, (long long)from, (long long)to);

