esp_err_t flux_sunspec_discover(flux_modbus_handle_t h, flux_sunspec_ctx_t *ctx)
{
    uint16_t regs[2];
    const int64_t deadline = esp_timer_get_time() + DISCOVER_BUDGET_US;

    for (size_t b = 0; b < sizeof(SUNS_BASES) / sizeof(SUNS_BASES[0]); b++) {
        if (esp_timer_get_time() >= deadline) {
            ESP_LOGW(TAG, "discovery budget exhausted probing base addresses");
            return ESP_ERR_NOT_FOUND;
        }
        uint16_t base = SUNS_BASES[b];
        esp_err_t rerr = flux_modbus_read_holding(h, base, 2, regs);
        if (rerr != ESP_OK) continue;
        if (regs[0] != SUNS_HI || regs[1] != SUNS_LO) continue;

        ESP_LOGI(TAG, "SunSpec marker found at base %u", base);

        /* Walk the model chain. First model header is at base + 2. */
