    // FLUX LOCAL PATCH — see flux-controller docs/adr/0014. Same reasoning as
    // ChipDnssdBrowse above, but this one was the more damaging of the two: with
    // both backends running, ESP mDNS would resolve successfully and the
    // OpenThread DNS client would then time out and deliver a LATE FAILURE on the
    // same callback, tearing down a session that had already succeeded
    // ("operational discovery failed: 32" for every device) — or dereference a
    // delegate the first completion had already freed (use-after-free, Load
    // access fault with MTVAL=0x48 in HandleNodeIdResolve).
    bool usedInfraBackend = false;
#if CHIP_DEVICE_CONFIG_ENABLE_WIFI || CHIP_DEVICE_CONFIG_ENABLE_ETHERNET
    if (ConnectivityMgr().IsWiFiStationProvisioned() || ESP32Utils::HasIPv6LinkLocalAddress(ESP32Utils::kDefaultEthernetNetifKey))
    {
        ReturnErrorOnFailure(EspDnssdResolve(service, interface, callback, context));
        usedInfraBackend = true;
    }
#endif
#if CHIP_DEVICE_CONFIG_ENABLE_THREAD && CHIP_DEVICE_CONFIG_ENABLE_THREAD_SRP_CLIENT && CHIP_DEVICE_CONFIG_ENABLE_THREAD_DNS_CLIENT
    if (!usedInfraBackend && ConnectivityMgr().IsThreadProvisioned())
    {
        ReturnErrorOnFailure(OpenThreadDnssdResolve(service, interface, callback, context));
    }
#endif
    (void) usedInfraBackend;
    return CHIP_NO_ERROR;
}

