/* Periodic idle sweep. Without this a session that goes quiet is only ever
 * reclaimed if another offer arrives to evict it — so a phone that wandered off
 * would hold a slot (and its TURN allocation) indefinitely. */
static void reaper_task(void *arg)
{
    (void)arg;
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(REAPER_TICK_MS));
        xSemaphoreTake(s_lock, portMAX_DELAY);
        retire_idle_locked();
        reap_dead();          /* also collects sessions libjuice already failed */
        xSemaphoreGive(s_lock);
    }
}

