    return bytes([(t << 3) | w]) + (vlq(len(d)) + d if w == 2 else vlq(d))

def decode_sdp(ans):
    i = 0; sdp = b""
    while i < len(ans):
        k = ans[i]; t = k >> 3; w = k & 7; i += 1
        if w == 0:
            while ans[i] & 0x80: i += 1
            i += 1
        elif w == 2:
            ln = 0; s = 0
            while True:
                b = ans[i]; i += 1; ln |= (b & 0x7f) << s; s += 7
                if not b & 0x80: break
            v = ans[i:i+ln]; i += ln
            if t == 2: sdp = v
    return sdp

