/* First TURN server from stored RemoteConfig. Returns false when none is
 * configured, in which case the agent gathers STUN-only.
 *
 * This existed as dead config until now: RemoteConfig.turn was accepted by
 * POST /remote/config, persisted, and even displayed in the app's Connection
 * screen "Relay" row — but nothing ever read it back, so cfg.turn_* stayed NULL
 * from the `{0}` initialiser and the controller could never produce a relay
 * candidate. Configuring a relay on the controller silently did nothing.
 *
 * That matters off-LAN: on a carrier CGNAT (phone on 5G) srflx<->srflx
 * hole-punching generally fails, and a relay candidate on at least one side is
 * what makes the tunnel possible. */
static bool resolve_turn(char *host, size_t host_max, uint16_t *port,
                         char *user, size_t user_max,
                         char *pass, size_t pass_max)
{
    host[0] = user[0] = pass[0] = '\0';
    *port = 0;

    uint8_t buf[flux_RemoteConfig_size];
    size_t len = 0;
    if (flux_remote_get_config(buf, &len, sizeof buf) != ESP_OK) return false;
    flux_RemoteConfig cfg = flux_RemoteConfig_init_zero;
    pb_istream_t is = pb_istream_from_buffer(buf, len);
    if (!pb_decode(&is, flux_RemoteConfig_fields, &cfg)) return false;
    if (cfg.turn_count == 0 || !cfg.turn[0].host[0]) return false;

    snprintf(host, host_max, "%s", cfg.turn[0].host);
    *port = cfg.turn[0].port ? (uint16_t)cfg.turn[0].port : 3478;
    snprintf(user, user_max, "%s", cfg.turn[0].username);
    snprintf(pass, pass_max, "%s", cfg.turn[0].credential);
    return true;
}

