/* ── kind migration (v0 -> v1) ─────────────────────────────────────────────
 *
 * Records written before devices were keyed by (kind, node_id) have no kind
 * field, so they are a different size and every reader rejects them on the exact
 * size check. Convert them in place at boot, once, guarded by a version key.
 *
 * kind is recovered from the only signal the old format had: whether node_id sat
 * in the reserved synthetic range. That is precisely the inference this refactor
 * removes — which is fine here, because reading the OLD format is the one place
 * it is still the truth.
 *
 * node_id is deliberately preserved rather than renumbered. Renumbering would
 * be tidier but would break every association the app holds against it (name,
 * room, energy role) and orphan the per-device history already in the energy CSV,
 * for no gain: kind now disambiguates, so a large legacy id is simply a value in
 * the MODBUS namespace.  */
#define DEV_VER_KEY  "ver"
#define STATE_KIND_V1  1
#define LEGACY_MODBUS_NODE_BASE  0x0100000000000000ULL

static uint8_t kind_from_legacy_node_id(uint64_t node_id)
{
    return (node_id >= LEGACY_MODBUS_NODE_BASE) ? FLUX_DEV_KIND_MODBUS
                                                : FLUX_DEV_KIND_MATTER;
}

/* v0 layouts, frozen — never track changes to the live structs. */
typedef struct {
    uint64_t node_id;
    uint32_t vendor_id;
    uint32_t product_id;
    uint32_t device_type;
    char     name[FLUX_DEVICE_NAME_MAX];
} dev_record_v0_t;

typedef struct {
    uint64_t node_id;
    uint8_t  cls;
} role_record_v0_t;

static void migrate_devices_v1(void)
{
    nvs_handle_t h;
    if (nvs_open(DEV_NS, NVS_READWRITE, &h) != ESP_OK) return;

    uint8_t ver = 0;
    nvs_get_u8(h, DEV_VER_KEY, &ver);
    if (ver >= STATE_KIND_V1) { nvs_close(h); return; }

    uint8_t cnt = 0;
    nvs_get_u8(h, DEV_CNT, &cnt);
    int converted = 0;
    for (size_t i = 0; i < cnt; i++) {
        char key[16];
        if (dev_key(key, sizeof(key), i) != ESP_OK) continue;
        dev_record_v0_t v0;
        size_t sz = sizeof(v0);
        if (nvs_get_blob(h, key, &v0, &sz) != ESP_OK || sz != sizeof(v0)) continue;

        flux_DeviceRecord v1 = {
            .node_id     = v0.node_id,
            .kind        = kind_from_legacy_node_id(v0.node_id),
            .vendor_id   = v0.vendor_id,
            .product_id  = v0.product_id,
            .device_type = v0.device_type,
        };
        snprintf(v1.name, sizeof(v1.name), "%s", v0.name);
        if (nvs_set_blob(h, key, &v1, sizeof(v1)) == ESP_OK) converted++;
    }
    nvs_set_u8(h, DEV_VER_KEY, STATE_KIND_V1);
    nvs_commit(h);
    nvs_close(h);
    ESP_LOGI(TAG, "device registry migrated to (kind, node_id): %d/%u record(s)",
             converted, (unsigned)cnt);
}

static void migrate_roles_v1(void)
{
    nvs_handle_t h;
    if (nvs_open(NVS_NAMESPACE, NVS_READWRITE, &h) != ESP_OK) return;

    size_t sz = 0;
    if (nvs_get_blob(h, NVS_KEY_ENERGY_ROLES, NULL, &sz) != ESP_OK || sz == 0) {
        nvs_close(h);
        return;
    }
    /* Already v1 if the size is a whole number of new records and not of old
     * ones; when both divide evenly the version key on the device namespace has
     * already been bumped, so this only runs once regardless. */
    if (sz % sizeof(role_record_v0_t) != 0) { nvs_close(h); return; }

    size_t n = sz / sizeof(role_record_v0_t);
    if (n > FLUX_ENERGY_ROLES_MAX) n = FLUX_ENERGY_ROLES_MAX;
    role_record_v0_t v0[FLUX_ENERGY_ROLES_MAX];
    size_t rd = sz;
    if (nvs_get_blob(h, NVS_KEY_ENERGY_ROLES, v0, &rd) != ESP_OK) {
        nvs_close(h);
        return;
    }

    flux_EnergyRoleRec v1[FLUX_ENERGY_ROLES_MAX];
    for (size_t i = 0; i < n; i++) {
        v1[i].node_id = v0[i].node_id;
        v1[i].kind    = kind_from_legacy_node_id(v0[i].node_id);
        v1[i].cls     = v0[i].cls;
    }
    if (nvs_set_blob(h, NVS_KEY_ENERGY_ROLES, v1, n * sizeof(v1[0])) == ESP_OK) {
        nvs_commit(h);
        ESP_LOGI(TAG, "energy roles migrated to (kind, node_id): %u entr(ies)",
                 (unsigned)n);
    }
    nvs_close(h);
}

static void state_migrate_kind_v1(void)
{
    nvs_handle_t h;
    uint8_t ver = 0;
    if (nvs_open(DEV_NS, NVS_READONLY, &h) == ESP_OK) {
        nvs_get_u8(h, DEV_VER_KEY, &ver);
        nvs_close(h);
    }
    if (ver >= STATE_KIND_V1) return;   /* already migrated */
    migrate_roles_v1();                 /* roles first: keyed off the same base */
    migrate_devices_v1();               /* bumps the version key */
}'''
