static const char *classify(uint64_t node_id, char *name, size_t name_len,
                            const char **source)
{
    name[0] = '\0';
    /* Resolve name from the device record regardless of class. */
    bool is_modbus = flux_is_modbus_node(node_id);
    const char *profile_cls = "unknown";
    if (is_modbus) {
        *source = "modbus";
        flux_ModbusRecord mb;
        if (flux_modbus_get_by_node(node_id, &mb) == ESP_OK) {
            strlcpy(name, mb.name, name_len);
            switch (mb.profile) {
                case REDACTED: profile_cls = "grid"; break;
                case REDACTED:  profile_cls = "pv";   break;
                default: break;
            }
        }
    } else {
        *source = "matter";
        flux_DeviceRecord dev;
        if (flux_device_get_by_node(node_id, &dev) == ESP_OK) {
            strlcpy(name, dev.name, name_len);
        }
        profile_cls = "load";  /* commissioned Matter device */
    }
    /* The user's energy-role assignment (pushed by the app) wins over the
     * heuristic — it's the only way the controller knows e.g. a Matter plug is
     * really a PV source or a battery. */
    const char *role = cls_str(flux_energy_role_of(node_id));
    return role ? role : profile_cls;
}

