 *
 * NVS namespace "flux_rooms":
 *   "count"   u8    — number of valid entries (0..FLUX_ROOMS_MAX)
 *   "id_ctr"  u16   — monotonic id counter; ids are never reused
 *   "rooms"   blob  — the entries, one flux_RoomRec each
 *
