 * would be silently adopted by whichever room happened to inherit the number —
 * a wrong answer that looks perfectly valid. With a monotonic counter, a stale
 * reference matches nothing and is reset to FLUX_ROOM_NONE instead. */

#define ROOM_NS      "flux_rooms"
#define ROOM_CNT     "count"
#define ROOM_ID_CTR  "id_ctr"
#define ROOM_BLOB    "rooms"

static flux_RoomRec      s_rooms[FLUX_ROOMS_MAX];
static size_t            s_rooms_n;
static bool              s_rooms_loaded;
static SemaphoreHandle_t s_rooms_mutex;
static StaticSemaphore_t s_rooms_mutex_buf;

/* Created at boot alongside the other state mutexes, never lazily in the lock:
 * the CoAP task writes rooms while the device-list handler reads them, so a
 * lazy first-use init races and can leave the table unguarded. */
static void rooms_mutex_init(void)
{
    s_rooms_mutex = xSemaphoreCreateMutexStatic(&s_rooms_mutex_buf);
}

static void rooms_lock(void)   { xSemaphoreTake(s_rooms_mutex, portMAX_DELAY); }
static void rooms_unlock(void) { xSemaphoreGive(s_rooms_mutex); }

static void rooms_load_locked(void)
{
    if (s_rooms_loaded) return;
    s_rooms_loaded = true;
    s_rooms_n      = 0;

    nvs_handle_t h;
    if (nvs_open(ROOM_NS, NVS_READONLY, &h) != ESP_OK) return;
    size_t sz = sizeof(s_rooms);
    if (nvs_get_blob(h, ROOM_BLOB, s_rooms, &sz) == ESP_OK)
        s_rooms_n = sz / sizeof(s_rooms[0]);
    nvs_close(h);
}

size_t flux_rooms_count(void)
{
    rooms_lock();
    rooms_load_locked();
    size_t n = s_rooms_n;
    rooms_unlock();
    return n;
}

size_t flux_rooms_get_all(flux_RoomRec *out, size_t max)
{
    rooms_lock();
    rooms_load_locked();
    size_t n = s_rooms_n < max ? s_rooms_n : max;
    if (out) memcpy(out, s_rooms, n * sizeof(s_rooms[0]));
    rooms_unlock();
    return n;
}

/* Reset every device whose room is no longer in [ids] back to No Room, so a
 * delete cannot leave a dangling reference. Runs after the list is persisted:
 * an interrupted run leaves some devices still pointing at a dead id, which the
 * next call repairs — whereas doing it first could clear rooms for a replace
 * that then fails. */
static void rooms_reap_orphans(const uint16_t *ids, size_t n_ids)
{
    size_t n = flux_device_count();
    for (size_t i = 0; i < n; i++) {
        flux_DeviceRecord rec;
        if (flux_device_get(i, &rec) != ESP_OK) continue;
        if (rec.room_id == FLUX_ROOM_NONE) continue;

        bool alive = false;
        for (size_t k = 0; k < n_ids; k++)
            if (ids[k] == rec.room_id) { alive = true; break; }
        if (alive) continue;

        ESP_LOGI(TAG, "room %u deleted: device %016llx (kind=%u) -> No Room",
                 (unsigned)rec.room_id, (unsigned long long)rec.node_id,
                 (unsigned)rec.kind);
        flux_device_set_room(rec.kind, rec.node_id, FLUX_ROOM_NONE);
    }
}

esp_err_t flux_rooms_set_all(flux_RoomRec *recs, size_t n)
{
    if (n > FLUX_ROOMS_MAX) return ESP_ERR_INVALID_SIZE;

    rooms_lock();
    rooms_load_locked();

    nvs_handle_t h;
    esp_err_t err = nvs_open(ROOM_NS, NVS_READWRITE, &h);
    if (err != ESP_OK) { rooms_unlock(); return err; }

    uint16_t id_ctr = 0;
    nvs_get_u16(h, ROOM_ID_CTR, &id_ctr);

    for (size_t i = 0; i < n; i++) {
        if (recs[i].id == FLUX_ROOM_NONE)      /* create */
            recs[i].id = ++id_ctr;
        recs[i].name[FLUX_ROOM_NAME_MAX - 1] = '\0';
    }

    memcpy(s_rooms, recs, n * sizeof(s_rooms[0]));
    s_rooms_n      = n;
    s_rooms_loaded = true;

    if (n == 0) {
        err = nvs_erase_key(h, ROOM_BLOB);
        if (err == ESP_ERR_NVS_NOT_FOUND) err = ESP_OK;
    } else {
        err = nvs_set_blob(h, ROOM_BLOB, s_rooms, n * sizeof(s_rooms[0]));
    }
    if (err == ESP_OK) err = nvs_set_u8(h, ROOM_CNT, (uint8_t)n);
    if (err == ESP_OK) err = nvs_set_u16(h, ROOM_ID_CTR, id_ctr);
    if (err == ESP_OK) err = nvs_commit(h);
    nvs_close(h);

    uint16_t ids[FLUX_ROOMS_MAX];
    for (size_t i = 0; i < n; i++) ids[i] = s_rooms[i].id;
    rooms_unlock();   /* released before touching the device table: that path
                       * takes the device lock, and holding both invites a
                       * lock-order inversion with the readers above. */

    if (err == ESP_OK) rooms_reap_orphans(ids, n);
    ESP_LOGI(TAG, "rooms: %u entr(ies), next id %u", (unsigned)n, (unsigned)(id_ctr + 1));
    return err;
}

