<script data-dc-script data-props='{"scenario":{"editor":"enum","options":["Solar surplus","Evening draw"],"default":"Solar surplus","section":"State"}}'>
class Component extends DCLogic {
  renderVals() {
    const day = (this.props.scenario ?? 'Solar surplus') === 'Solar surplus';
    const soc = day ? 64 : 38;

    const srcRaw = day
      ? [{ short: 'SOLAR 2.4', kw: 2.4, color: '#F6D08A' }]
      : [{ short: 'BATTERY 0.9', kw: 0.9, color: '#A9E0C0' },
         { short: 'GRID 0.7', kw: 0.7, color: '#F2A9A0' }];
    const useRaw = day
      ? [{ short: 'HOME 1.1', kw: 1.1, color: '#F3B8D6' },
         { short: 'BATTERY 0.9', kw: 0.9, color: '#A9E0C0' },
         { short: 'GRID 0.4', kw: 0.4, color: '#A9E0C0' }]
      : [{ short: 'HOME 1.6', kw: 1.6, color: '#F3B8D6' }];

    const total = srcRaw.reduce((a, s) => a + s.kw, 0);
    const pct = (v) => (v / total) * 100;
    const sources = srcRaw.map((s) => ({ ...s, pct: pct(s.kw) }));
    const uses = useRaw.map((u) => ({ ...u, pct: pct(u.kw) }));

    // Greedy allocation of each source to each use, in order. That is the whole
    // Sankey: a ribbon is one source paying for part of one use, and its width
    // is how much. No layout library needed at this scale.
    const W = 330, H = 56, GAP = 3;
    const px = (v) => (v / total) * (W - GAP * Math.max(sources.length, uses.length));
    const ribbons = [];
    let si = 0, ui = 0, sLeft = sources[0].kw, uLeft = uses[0].kw;
    let sx = 0, ux = 0;
    while (si < sources.length && ui < uses.length) {
      const take = Math.min(sLeft, uLeft);
      const w = px(take);
      ribbons.push({
        color: sources[si].color,
        points: [sx, 0, sx + w, 0, ux + w, H, ux, H].join(' '),
      });
      sx += w; ux += w; sLeft -= take; uLeft -= take;
      if (sLeft <= 0.0001) { si++; sx += GAP; sLeft = sources[si] ? sources[si].kw : 0; }
      if (uLeft <= 0.0001) { ui++; ux += GAP; uLeft = uses[ui] ? uses[ui].kw : 0; }
    }

    const filled = Math.round(soc / 10);
    const cells = Array.from({ length: 10 }, (_, i) => ({
      fill: i < filled ? '#A9E0C0' : 'rgba(255,255,255,0.12)',
    }));

    return {
      sources, uses, ribbons, cells,
      socLabel: soc + '%',
      batNote: day ? 'charging' : 'discharging',
      totalLabel: total.toFixed(1) + ' kW',
    };
  }
}
</script>
</body>
</html>
