<html>
<head>
  <meta charset="utf-8">
  <script src="./support.js"></script>
</head>
<body>
<x-dc>
<helmet>
  <style>
    body { margin: 0; background: #0E1311;
           font-family: system-ui, -apple-system, "Segoe UI", sans-serif; }
    a { color: #6DC9A2; } a:hover { color: #8FDCBB; }
    .flow { stroke-width: 2; stroke-linecap: round; fill: none;
            stroke-dasharray: 3 7; animation: drift 1.1s linear infinite; }
    @keyframes drift { to { stroke-dashoffset: -10; } }
  </style>
</helmet>

<div style="width: 390px; padding: 16px; box-sizing: border-box; background: #0E1311;">

  <div style="display: flex; justify-content: space-between; align-items: baseline; padding: 0 4px 12px;">
    <div style="font-family: ui-monospace, Menlo, monospace; font-size: 11px; font-weight: 700; letter-spacing: 2.4px; color: #8A968F;">ENERGY FLOW</div>
    <div style="font-family: ui-monospace, Menlo, monospace; font-size: 10px; letter-spacing: 1px; color: #5E6A64;">LIVE</div>
  </div>

  <div style="background: #121815; border: 1px solid rgba(255,255,255,0.10); border-radius: 22px; padding: 14px 14px 16px;">

    <div style="padding: 2px 4px 10px;">
      <div style="font-size: 22px; font-weight: 700; color: #F2F5F3; letter-spacing: -0.4px; line-height: 1.15;">{{ headline }}</div>
      <div style="font-size: 12px; color: #8A968F; padding-top: 2px;">{{ headnote }}</div>
    </div>

    <!-- Supply sits above the house, demand below it. The house is the hinge:
         everything above flows in, everything below is where it went. -->
    <div style="position: relative; height: 338px;">
      <svg viewBox="0 0 330 338" style="position: absolute; inset: 0; width: 100%; height: 100%;">
        <sc-for list="{{ links }}" as="l" hint-placeholder-count="4">
          <line class="flow" x1="{{ l.x1 }}" y1="{{ l.y1 }}" x2="{{ l.x2 }}" y2="{{ l.y2 }}" style="stroke: {{ l.color }}"></line>
        </sc-for>
      </svg>

      <sc-for list="{{ nodes }}" as="n" hint-placeholder-count="6">
        <div style="position: absolute; left: {{ n.left }}px; top: {{ n.top }}px; transform: translate(-50%, -50%); width: {{ n.width }}px; box-sizing: border-box; padding: 7px 9px 8px; background: #0E1311; border: 1.4px solid {{ n.color }}; border-radius: 14px; opacity: {{ n.dim }};">
          <div style="font-family: ui-monospace, Menlo, monospace; font-size: 8.5px; font-weight: 700; letter-spacing: 0.8px; color: {{ n.color }};">{{ n.label }}</div>
          <div style="font-size: 15px; font-weight: 700; color: #F2F5F3; letter-spacing: -0.2px;">{{ n.value }}</div>
          <sc-if value="{{ n.soc }}" hint-placeholder-val="{{ true }}">
            <div style="display: flex; align-items: center; gap: 6px; padding-top: 5px;">
              <div style="position: relative; flex-grow: 1; height: 3px; border-radius: 2px; background: rgba(255,255,255,0.14);">
                <div style="position: absolute; left: 0; top: 0; bottom: 0; width: {{ n.socPct }}%; border-radius: 2px; background: {{ n.color }};"></div>
              </div>
              <div style="font-family: ui-monospace, Menlo, monospace; font-size: 9.5px; font-weight: 700; color: #8A968F;">{{ n.socLabel }}</div>
            </div>
          </sc-if>
        </div>
      </sc-for>
    </div>
  </div>
</div>
</x-dc>

<script data-dc-script data-props='{"scenario":{"editor":"enum","options":["Solar surplus","Evening draw"],"default":"Solar surplus","section":"State"}}'>
class Component extends DCLogic {
  renderVals() {
    const S = {
      'Solar surplus': { solar:6.2, gridImport:0, gridExport:0, batteryIn:0.3, batteryOut:0,
        batterySoc:64, heatPump:1.4, wallbox:3.6, carSoc:62, homeRest:0.9,
        head:'Solar is covering everything', note:'car is taking the surplus' },
      'Evening draw': { solar:0, gridImport:2.1, gridExport:0, batteryIn:0, batteryOut:1.2,
        batterySoc:38, heatPump:2.2, wallbox:0, carSoc:78, homeRest:1.1,
        head:'Grid and battery are carrying the house', note:'heat pump is the load' },
    };
    const s = S[this.props.scenario ?? 'Solar surplus'];
    const kw = (v) => v.toFixed(1) + ' kW';

    // Six anchors on a 330x338 field. Supply on the top row, the house in the
    // middle, the two big consumers below it.
    const P = { solar:[165,28], grid:[58,110], batt:[272,110], home:[165,186], heat:[62,300], car:[268,300] };

    const on = (v) => (v > 0.05 ? '1' : '0.35');   // idle assets stay, dimmed
    const battCharging = s.batteryIn > 0;
    const exporting = s.gridExport > 0;

    const nodes = [
      { label:'SOLAR', value:kw(s.solar), color:'#F6D08A', at:P.solar, width:104, dim:on(s.solar) },
      { label: exporting ? 'GRID EXPORT' : 'GRID IMPORT', value:kw(exporting ? s.gridExport : s.gridImport),
        color: exporting ? '#A9E0C0' : '#F2A9A0', at:P.grid, width:100, dim:on(s.gridImport + s.gridExport) },
      { label: battCharging ? 'BATTERY CHARGING' : (s.batteryOut > 0 ? 'BATTERY OUT' : 'BATTERY IDLE'),
        value:kw(battCharging ? s.batteryIn : s.batteryOut), color:'#A9E0C0', at:P.batt, width:112,
        dim:'1', soc:true, socPct:s.batterySoc, socLabel:s.batterySoc + '%' },
      { label:'HOME', value:kw(s.homeRest), color:'#F3B8D6', at:P.home, width:104, dim:'1' },
      { label:'HEAT PUMP', value:kw(s.heatPump), color:'#A9D8EE', at:P.heat, width:104, dim:on(s.heatPump) },
      // The wallbox reports the power; the percentage belongs to the car. One
      // node, two facts — which is why it still says 78% while drawing nothing.
      { label:'WALLBOX / CAR', value:kw(s.wallbox), color:'#CDBBEF', at:P.car, width:112,
        dim:'1', soc:true, socPct:s.carSoc, socLabel:s.carSoc + '%' },
    ].map((n) => ({ ...n, left:n.at[0], top:n.at[1], soc:n.soc ?? false, socPct:n.socPct ?? 0, socLabel:n.socLabel ?? '' }));

    const link = (a, b, color) => ({ x1:a[0], y1:a[1], x2:b[0], y2:b[1], color });
    const links = [];
    if (s.solar > 0.05) links.push(link(P.solar, P.home, '#F6D08A'));
    if (s.gridImport > 0.05) links.push(link(P.grid, P.home, '#F2A9A0'));
    if (s.gridExport > 0.05) links.push(link(P.home, P.grid, '#A9E0C0'));
    if (s.batteryIn > 0.05) links.push(link(P.home, P.batt, '#A9E0C0'));
    if (s.batteryOut > 0.05) links.push(link(P.batt, P.home, '#A9E0C0'));
    if (s.heatPump > 0.05) links.push(link(P.home, P.heat, '#A9D8EE'));
    if (s.wallbox > 0.05) links.push(link(P.home, P.car, '#CDBBEF'));

    return { nodes, links, headline:s.head, headnote:s.note };
  }
}
</script>
</body>
</html>
EOF
