new_logic = '''class Component extends DCLogic {
  renderVals() {
    const S = {
      'Solar surplus': { solar:6.2, gridImport:0, gridExport:0, batteryIn:0.3, batteryOut:0,
        batterySoc:64, heatPump:1.4, wallbox:3.6, carSoc:62, homeRest:0.9 },
      'Evening draw': { solar:0, gridImport:2.1, gridExport:0, batteryIn:0, batteryOut:1.2,
        batterySoc:38, heatPump:2.2, wallbox:0, carSoc:78, homeRest:1.1 },
    };
    const s = S[this.props.scenario ?? 'Solar surplus'];

    // Only non-zero participants get a band. The bar is always full width, so
    // its SEGMENTS are the reading: how the house is being paid for right now.
    const srcRaw = [
      { short:'SOLAR', kw:s.solar, color:'#F6D08A' },
      { short:'GRID', kw:s.gridImport, color:'#F2A9A0' },
      { short:'BATTERY', kw:s.batteryOut, color:'#A9E0C0' },
    ].filter((x) => x.kw > 0.05);
    const useRaw = [
      { short:'HOME', kw:s.homeRest, color:'#F3B8D6' },
      { short:'HEAT', kw:s.heatPump, color:'#A9D8EE' },
      { short:'CAR', kw:s.wallbox, color:'#CDBBEF' },
      { short:'BATTERY', kw:s.batteryIn, color:'#A9E0C0' },
      { short:'GRID', kw:s.gridExport, color:'#A9E0C0' },
    ].filter((x) => x.kw > 0.05);

    const total = srcRaw.reduce((a, x) => a + x.kw, 0);
    const label = (x) => ({ ...x, short: x.short + ' ' + x.kw.toFixed(1) });
    const sources = srcRaw.map(label);
    const uses = useRaw.map(label);

    const W = 330, H = 56, GAP = 3;
    const sScale = (W - GAP * (sources.length - 1)) / total;
    const uScale = (W - GAP * (uses.length - 1)) / total;
    const ribbons = [];
    let si = 0, ui = 0, sLeft = sources[0].kw, uLeft = uses[0].kw, sx = 0, ux = 0;
    while (si < sources.length && ui < uses.length) {
      const take = Math.min(sLeft, uLeft);
      ribbons.push({ color: sources[si].color,
        points: [sx, 0, sx + take * sScale, 0, ux + take * uScale, H, ux, H].join(' ') });
      sx += take * sScale; ux += take * uScale; sLeft -= take; uLeft -= take;
      if (sLeft <= 0.0001) { si++; sx += GAP; sLeft = sources[si] ? sources[si].kw : 0; }
      if (uLeft <= 0.0001) { ui++; ux += GAP; uLeft = uses[ui] ? uses[ui].kw : 0; }
    }

    const cells = (pct, color) => Array.from({ length: 10 }, (_, i) => ({
      fill: i < Math.round(pct / 10) ? color : 'rgba(255,255,255,0.12)' }));

    // Charge levels are STATE, not flow: they keep their row when the bar above
    // shows nothing moving to or from them.
    const gauges = [
      { name:'BATTERY', color:'#A9E0C0', pct:s.batterySoc, label:s.batterySoc + '%',
        note: s.batteryIn > 0.05 ? 'charging' : (s.batteryOut > 0.05 ? 'discharging' : 'idle'),
        cells: cells(s.batterySoc, '#A9E0C0') },
      { name:'CAR', color:'#CDBBEF', pct:s.carSoc, label:s.carSoc + '%',
        note: s.wallbox > 0.05 ? 'charging' : 'plugged in',
        cells: cells(s.carSoc, '#CDBBEF') },
    ];

    return { sources, uses, ribbons, gauges, totalLabel: total.toFixed(1) + ' kW' };
  }
}
'''
