class EnergyFlowCard extends StatelessWidget {
  const EnergyFlowCard({super.key});

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final s  = context.watch<DeviceProvider>().energySummary;

