        textBaseline: TextBaseline.alphabetic,
        children: [
          Text('$v $u', style: const TextStyle(
              fontSize: 28, fontWeight: FontWeight.w700, letterSpacing: -0.6)),
          const SizedBox(width: 9),
          const Text('HOME NOW', style: TextStyle(
              fontFamily: 'monospace', fontSize: 10, fontWeight: FontWeight.w700,
              letterSpacing: 1.4, color: _homeColor)),
        ],
      ),
    );
  }
}

class _Gauge {
  const _Gauge({required this.name, required this.color, required this.percent});
  final String name;
  final Color  color;
  final int    percent;
}

class _GaugeRow extends StatelessWidget {
  const _GaugeRow({required this.gauge});
  final _Gauge gauge;

  static const _cells = 10;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final filled = (gauge.percent / 100 * _cells).round();

    return Container(
      decoration: BoxDecoration(
        border: Border(top: BorderSide(color: cs.outlineVariant, width: 1)),
      ),
      padding: const EdgeInsets.only(top: 10, bottom: 2),
      child: Row(
        children: [
          SizedBox(
            width: 82,
            child: Text('${gauge.name} SOC', style: TextStyle(
                fontFamily: 'monospace', fontSize: 10, fontWeight: FontWeight.w700,
                letterSpacing: 0.5, color: gauge.color)),
          ),
          Expanded(
            child: Row(
              children: [
                for (var i = 0; i < _cells; i++) ...[
                  if (i > 0) const SizedBox(width: 2),
                  Expanded(child: Container(
                    height: 12,
                    decoration: BoxDecoration(
                      color: i < filled
                          ? gauge.color
                          : cs.onSurface.withValues(alpha: 0.12),
                      borderRadius: BorderRadius.circular(2),
                    ),
                  )),
                ],
              ],
            ),
          ),
          const SizedBox(width: 10),
          SizedBox(
            width: 72,
            child: Text('${gauge.percent}%',
                textAlign: TextAlign.right,
                style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
