#include "flux_controller.h"
#include "flux_commission.h"

/* ── Helpers ─────────────────────────────────────────────────────────────── */

/* libcoap holds the response body pointer across block2 requests (it does NOT
 * copy when no release_func is given) and paginates from it on each follow-up
 * block. Callers free their buffer right after this returns, which is fine for a
 * single-block reply but corrupts a multi-block one — libcoap then reads freed
 * memory, the body differs between blocks, and the client aborts with
 * ResourceChanged (hit by /energy/history and /modbus/rawdump). Hand libcoap its
 * OWN copy plus a release callback so the body stays stable for the whole
 * block-wise transfer; the caller's buffer lifetime no longer matters. */
static void proto_body_release(coap_session_t *session, void *app_ptr)
{
    (void)session;
    free(app_ptr);
}

void coap_send_proto(coap_resource_t *resource,
                     coap_session_t  *session,
                     const coap_pdu_t *request,
                     coap_pdu_t       *response,
                     const uint8_t    *buf, size_t len)
{
    coap_pdu_set_code(response, COAP_RESPONSE_CODE_CONTENT);

    /* Stable, content-derived ETag (FNV-1a). A block-wise (block2) transfer
     * re-runs the handler per block; with etag=0 libcoap auto-assigns a fresh
     * ETag each call, so the client sees the resource "change" mid-transfer and
     * aborts (ResourceChanged). Deriving the ETag from the body keeps it
     * identical across blocks of the same body (and differs when it changes). */
    uint64_t etag = 1469598103934665603ULL;
    for (size_t i = 0; i < len; i++) { etag ^= buf[i]; etag *= 1099511628211ULL; }
    if (etag == 0) etag = 1;

    uint8_t *owned = len ? (uint8_t *)malloc(len) : NULL;
    if (owned) memcpy(owned, buf, len);
    coap_add_data_large_response(resource, session, request, response,
                                 NULL,
                                 COAP_MEDIATYPE_APPLICATION_OCTET_STREAM,
                                 -1, etag, len,
                                 owned ? owned : buf,
                                 owned ? proto_body_release : NULL,
                                 owned);
}

void coap_send_proto_block2(coap_session_t *session, const coap_pdu_t *request,
                            coap_pdu_t *response, const uint8_t *body, size_t len)
{
    (void)session;
    /* Manual RFC7959 block2, with a fixed content-derived (FNV-1a) ETag on EVERY
     * block. coap_add_data_large_response adds the ETag only when it sets up the
     * transfer (block 0); on a mid-stream block served by a re-invoked handler
     * (the async separate-response path used by large deferred bodies) it drops
     * the ETag, so the client sees the resource "change" and aborts
     * (ResourceChanged). Setting options ourselves keeps the ETag identical
     * across all blocks. The caller must serve the SAME body for every block
     * (i.e. cache it), which the async endpoints do. */
    uint64_t etag = 1469598103934665603ULL;
    for (size_t i = 0; i < len; i++) { etag ^= body[i]; etag *= 1099511628211ULL; }
    if (etag == 0) etag = 1;

    coap_block_t blk;
    uint32_t num = 0, szx = 6;                 /* default block size 1024 */
    if (coap_get_block(request, COAP_OPTION_BLOCK2, &blk)) { num = blk.num; szx = blk.szx; }
    if (szx > 6) szx = 6;
    size_t bsize = (size_t)1 << (szx + 4);
    size_t off   = (size_t)num * bsize;
    if (off > len) off = len;
    size_t chunk = (len - off > bsize) ? bsize : (len - off);
    unsigned more = (off + chunk < len) ? 1u : 0u;

    coap_pdu_set_code(response, COAP_RESPONSE_CODE_CONTENT);
    /* Options must be added in ascending number order:
     * ETag(4) < Content-Format(12) < Block2(23) < Size2(28). */
    uint8_t b[8]; size_t n;
    n = coap_encode_var_safe8(b, sizeof b, etag);
    coap_add_option(response, COAP_OPTION_ETAG, n, b);
    n = coap_encode_var_safe(b, sizeof b, COAP_MEDIATYPE_APPLICATION_OCTET_STREAM);

