 *
 * So the snapshot is cached for as long as a transfer can plausibly take. One
 * entry is enough: a client pages one resource at a time, and a second reader
 * simply takes a fresh snapshot. */
#define CLUSTER_SNAP_TTL_US  (15LL * 1000000)

static struct {
    uint8_t  kind;
    uint64_t node_id;
    char    *json;
    size_t   len;
