static void cluster_snap_put(uint8_t kind, uint64_t node_id, const char *json, size_t len)
{
    free(s_cluster_snap.json);
    s_cluster_snap.json = NULL;
    s_cluster_snap.len  = 0;
    if (json && len) {
        s_cluster_snap.json = (char *)malloc(len);
        if (s_cluster_snap.json) {
            memcpy(s_cluster_snap.json, json, len);
            s_cluster_snap.len = len;
        }
    }
    s_cluster_snap.kind     = kind;
    s_cluster_snap.node_id  = node_id;
    s_cluster_snap.taken_us = esp_timer_get_time();
}

/* The cached body for this device, or NULL if there is none or it has aged out. */
static const char *cluster_snap_get(uint8_t kind, uint64_t node_id, size_t *len)
{
    if (!s_cluster_snap.json || s_cluster_snap.node_id != node_id
        || s_cluster_snap.kind != kind) return NULL;
    if (esp_timer_get_time() - s_cluster_snap.taken_us > CLUSTER_SNAP_TTL_US) return NULL;
    *len = s_cluster_snap.len;
    return s_cluster_snap.json;
}

