  factory EnergyHistoryData.fromProto($proto.EnergyHistory h) {
    final bucketSec = h.bucketSeconds == 0 ? 900 : h.bucketSeconds;
    final start = h.start.toInt(); // epoch seconds of bucket 0
    final perHour = bucketSec / 3600.0; // fraction of an hour per bucket

    // The bucket containing the query's end time is still in progress: it holds
    // only the energy accrued so far this interval, so it always reads low and
    // climbs as the interval fills. Drop it (and anything at/after it) so the
    // chart and totals reflect complete buckets only. `to` and `start` share the
    // controller's clock, so this needs no local wall-clock. Guard against `to`
    // being unset/pre-start (older responses / tests) → no cutoff.
    final to = h.to.toInt();
    final inProgressIndex =
        to > start ? (to - start) ~/ bucketSec : 1 << 30;
    final buckets = [
      for (final b in h.buckets)
        if (b.index < inProgressIndex) b,
    ];

    // Wh → average W over the bucket.
    double watts(int wh) => wh / perHour;

    final points = <EnergyHistoryPoint>[];
    var pvWh = 0, impWh = 0, expWh = 0, loadWh = 0, batChgWh = 0, batDisWh = 0;
    for (final b in buckets) {
      pvWh += b.pvWh;
      impWh += b.gridImportWh;
      expWh += b.gridExportWh;
      loadWh += b.loadWh;
      batChgWh += b.batteryChargeWh;
      batDisWh += b.batteryDischargeWh;
      points.add(EnergyHistoryPoint(
        time: DateTime.fromMillisecondsSinceEpoch(
            (start + b.index * bucketSec) * 1000),
        pvW: watts(b.pvWh),
        gridImportW: watts(b.gridImportWh),
        gridExportW: watts(b.gridExportWh),
        loadW: watts(b.loadWh),
      ));
    }
    // Per-device PV breakdown (index-aligned to buckets), if the controller
    // reported it. Each series' wh[] is dense and aligned to h.buckets by index.
    final pvSeries = <PvDeviceSeries>[];
    for (final s in h.deviceSeries) {
      if (s.cls != $proto.EnergyClass.ENERGY_CLASS_PV) continue;
      var total = 0;
      final watts = <double>[];
      for (var i = 0; i < points.length; i++) {
        final wh = i < s.wh.length ? s.wh[i] : 0;
        total += wh;
        watts.add(wh / perHour);
      }
      pvSeries.add(PvDeviceSeries(
        kind: DeviceKind.fromWire(s.kind.value),
        nodeId: s.nodeId.toInt(),
        name: s.name.isNotEmpty ? s.name : 'PV ${s.nodeId.toInt()}',
        wattsPerBucket: watts,
        kwh: total / 1000.0,
      ));
    }

    return EnergyHistoryData(
      points: points,
      bucket: Duration(seconds: bucketSec),
      timeSynced: h.timeSynced,
      truncated: h.truncated,
      pvKwh: pvWh / 1000.0,
      gridImportKwh: impWh / 1000.0,
      gridExportKwh: expWh / 1000.0,
      loadKwh: loadWh / 1000.0,
      batteryChargeKwh: batChgWh / 1000.0,
      batteryDischargeKwh: batDisWh / 1000.0,
      pvSeries: pvSeries,
    );
  }
}

/// price in force at that time. Null when there's no overlap with coverage.
///
/// Priced per bucket, never at a window average, deliberately: PV peaks around
/// midday, which is exactly when the day-ahead curve tends to bottom out, so an
/// average would systematically overstate what self-consumption was worth under
/// a dynamic tariff. Valued at the *gross* consumer price (markup + VAT already
/// applied in [fromProto]), because that is the price that was avoided — which
/// is why this is typically several times [exportRevenueCents] for the same kWh.
///
/// This is a counterfactual, not a cash flow — unlike [exportRevenueCents],
/// no money changed hands. Battery round-trips are excluded: the controller
/// reports battery only as a window total, not per bucket, so a discharge
/// can't be priced by the time it happened.
///
/// Cannot overstate itself: `consumptionW = pv + import − export`, so
/// `pv − export ≤ consumptionW` for any non-negative import.
double? selfConsumptionSavingCents(EnergyHistoryData? history) {
  if (history == null || history.points.isEmpty || points.isEmpty) return null;
  final bucketHours = history.bucket.inSeconds / 3600.0;
  var cents = 0.0;
  var any = false;
  for (final p in history.points) {
    final price = currentAt(p.time);
    if (price == null) continue; // spot varies by hour → only where priced
    final selfW = p.pvW - p.gridExportW; // generated, minus what left the house
    if (selfW <= 0) continue;
    cents += selfW * bucketHours / 1000.0 * price.ctPerKwh;
    any = true;
  }
  return any ? cents : null;
}

/// Revenue (in cents) from energy exported to the grid over the whole
/// [history] window (the previous 24 h), valued at the flat feed-in tariff
/// [feedInCt] (Einspeisevergütung). Unlike import, the feed-in rate is flat,
/// so it doesn't need the spot curve and covers the full window.
double? exportRevenueCents(EnergyHistoryData? history, double feedInCt) {
  if (history == null || history.points.isEmpty || feedInCt <= 0) return null;
  return history.gridExportKwh * feedInCt;

