      if (hiI < 0 || v > series[hiI]!) hiI = i;
      final o = Offset(_xForIndex(i, series.length, size.width), y(v));
      if (!started) { path.moveTo(o.dx, o.dy); started = true; } else { path.lineTo(o.dx, o.dy); }
