      final right = o.dx > size.width * 0.6;
      _paintLabel(canvas, '${v.toStringAsFixed(0)} $suffix',
          Offset(o.dx + (right ? -6 : 6), o.dy - 12), c, size: 8.5,
          rightAlign: right);
    }
