// ─── Solar production forecast ───────────────────────────────────────────────
// The controller forecasts its own PV production: it fetches only the weather
// (irradiance) and runs the site model — sun position, plane-of-array
// transposition, temperature derate, inverter clipping — on-device. See
// docs/solar-forecast.md.

// One roof plane.
//
// AZIMUTH CONVENTION: the compass bearing the panel surface FACES, degrees
// clockwise from true north. 0 = N, 90 = E, 180 = S, 270 = W. (Note this
// differs from pvlib's solar-azimuth convention and from Forecast.Solar's
// south-relative -90..+90; the value here is a plain compass bearing.)
message SolarPlane {
    uint32 tilt_deg    = 1;  // 0 = horizontal, 90 = vertical
    uint32 azimuth_deg = 2;  // compass bearing faced, 0..359 (180 = due south)
    uint32 kwp_w       = 3;  // DC peak capacity in watts-peak (16.5 kWp = 16500)
}

// GET/POST /solar/config — forecast acquisition + site model (persisted in NVS).
// Writes are LAN-only, like the other config surfaces (ADR-0012).
message SolarConfig {
    bool     enabled              = 1;  // default false → no outbound requests at all
    string   provider             = 2;  // "openmeteo"
    sint32   latitude_udeg        = 3;  // micro-degrees, +N (49.477491 → 49477491)
    sint32   longitude_udeg       = 4;  // micro-degrees, +E
    // Only planes[0] is modelled today. The field is repeated from day one so
    // multi-plane (east/west split) support is a firmware change and never a
    // wire migration.
    repeated SolarPlane planes    = 5;
    // Inverter AC clipping limit in watts; 0 = no clipping. Measured arrays are
    // routinely DC-oversized ~1.4x, and without this clear-sky midday hours
    // over-predict by ~15%.
    uint32   inverter_ac_w        = 6;
    uint32   system_loss_pct      = 7;  // soiling+mismatch+wiring; 0 = default 13
    uint32   albedo_pct           = 8;  // ground reflectance; 0 = default 20
    // Module power temperature coefficient, ppm per kelvin, negative. 0 =
    // default -4000 (i.e. -0.40 %/K).
    sint32   temp_coeff_ppm_per_k = 9;
}

