        if (subject != null)
          Padding(
            padding: const EdgeInsets.only(left: 25, bottom: 4),
            child: Text('applies to $subject',
                style: TextStyle(fontSize: 11, color: cs.onSurfaceVariant)),
          ),
      ],
    );
  }
}
