              headline: 'NO ${category.label.toUpperCase()}',
              subline: 'NOTHING HERE YET',
            )
          : CustomScrollView(
              slivers: [
                if (showScene) _EnergyCards(provider: provider),
                if (category.groupsByRoom)
                  ..._roomSlivers(context, provider, color)
                else
                  SliverPadding(
                    padding: const EdgeInsets.fromLTRB(16, 12, 16, 88),
                    sliver: _deviceGrid(context, devices),
                  ),
              ],
            ),
    );
  }

  /// One section per room: the room's shared controls, then its devices.
  ///
  /// Rooms with nothing in this category are skipped, matching the home screen —
  /// a header over an empty grid says nothing.
  List<Widget> _roomSlivers(
      BuildContext context, DeviceProvider provider, Color accent) {
    final groups = [
      for (final (room, views) in provider.deviceViewsByRoom)
        DeviceGroup(
          room: room,
          devices: [for (final v in views) if (category.matches(v)) v],
        ),
    ];

    return [
      for (final g in groups)
        if (!g.isEmpty) ...[
          SliverPadding(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
            sliver: SliverToBoxAdapter(
              // A room whose devices share no control gets a plain header
              // instead — the card would render to nothing and take the room's
              // name with it.
              child: g.supports(GroupControl.onOff) ||
                      g.supports(GroupControl.brightness) ||
                      g.supports(GroupControl.colorTemp)
                  ? RoomGroupCard(group: g, accent: accent)
                  : Padding(
                      padding: const EdgeInsets.only(bottom: 8),
                      child: SectionLabel(g.room.name),
                    ),
            ),
          ),
          SliverPadding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 4),
            sliver: _deviceGrid(context, g.devices),
          ),
        ],
      const SliverPadding(padding: EdgeInsets.only(bottom: 88)),
    ];
  }

  SliverGrid _deviceGrid(BuildContext context, List<DeviceView> devices) {
    return SliverGrid(
      gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
        maxCrossAxisExtent: 180,
        mainAxisSpacing: 12,
        crossAxisSpacing: 12,
      ),
      delegate: SliverChildBuilderDelegate(
        (ctx, i) => DeviceCard(
          deviceId: devices[i].id,
          onTap: () => context.push('/device/${devices[i].id}'),
        ),
        childCount: devices.length,
      ),
    );
  }
}

