    if (local.isEmpty || local == cd.name) continue;
    if (await svc.setDeviceMeta(nodeId, kind: kind, name: local)) pushed++;
  }
  await _store.markNamesUploaded();
  if (pushed > 0) debugPrint('DeviceProvider: uploaded $pushed device name(s)');
}

