size_t flux_rooms_get_all(flux_RoomRec *out, size_t max)
{
    rooms_lock();
    rooms_load_locked();
    size_t n = s_rooms_n < max ? s_rooms_n : max;
    if (out) memcpy(out, s_rooms, n * sizeof(s_rooms[0]));
    rooms_unlock();
    return n;
}

/* Reset every device whose room is no longer in [ids] back to No Room, so a
 * delete cannot leave a dangling reference. Runs after the list is persisted:
 * an interrupted run leaves some devices still pointing at a dead id, which the
 * next call repairs — whereas doing it first could clear rooms for a replace
 * that then fails. */
static void rooms_reap_orphans(const uint16_t *ids, size_t n_ids)
{
    size_t n = flux_device_count();
    for (size_t i = 0; i < n; i++) {
        flux_DeviceRecord rec;
        if (flux_device_get(i, &rec) != ESP_OK) continue;
        if (rec.room_id == FLUX_ROOM_NONE) continue;

        bool alive = false;
        for (size_t k = 0; k < n_ids; k++)
            if (ids[k] == rec.room_id) { alive = true; break; }
        if (alive) continue;

        ESP_LOGI(TAG, "room %u deleted: device %016llx (kind=%u) -> No Room",
                 (unsigned)rec.room_id, (unsigned long long)rec.node_id,
                 (unsigned)rec.kind);
        flux_device_set_room(rec.kind, rec.node_id, rec.endpoint, FLUX_ROOM_NONE);
    }
}

